CREATE EXTENSION IF NOT EXISTS pg_graphql WITH SCHEMA graphql;
GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT USAGE ON SCHEMA graphql TO anon, authenticated, service_role;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO anon, authenticated;

CREATE POLICY "public_read_products" ON products FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "public_read_collections" ON collections FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "public_read_medias" ON medias FOR SELECT TO anon, authenticated USING (true);

-- Saved shipping addresses: contact fields, default flag, RLS
ALTER TABLE address ADD COLUMN IF NOT EXISTS full_name TEXT;
ALTER TABLE address ADD COLUMN IF NOT EXISTS email TEXT;
ALTER TABLE address ADD COLUMN IF NOT EXISTS mobile TEXT;
ALTER TABLE address ADD COLUMN IF NOT EXISTS is_default BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE address ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT NOW();

ALTER TABLE address ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "address_select_own" ON address;
CREATE POLICY "address_select_own" ON address
  FOR SELECT USING (auth.uid() = "userProfileId");

DROP POLICY IF EXISTS "address_insert_own" ON address;
CREATE POLICY "address_insert_own" ON address
  FOR INSERT WITH CHECK (auth.uid() = "userProfileId");

DROP POLICY IF EXISTS "address_update_own" ON address;
CREATE POLICY "address_update_own" ON address
  FOR UPDATE USING (auth.uid() = "userProfileId");

DROP POLICY IF EXISTS "address_delete_own" ON address;
CREATE POLICY "address_delete_own" ON address
  FOR DELETE TO authenticated USING (auth.uid() = "userProfileId");

CREATE INDEX IF NOT EXISTS address_user_profile_id_idx ON address ("userProfileId");
CREATE INDEX IF NOT EXISTS address_user_default_idx ON address ("userProfileId", is_default DESC, created_at DESC);

GRANT SELECT, INSERT, UPDATE, DELETE ON address TO authenticated;
GRANT SELECT ON address TO anon;

-- Payment integrations config + order tracking columns

create table if not exists public.api_settings (
  key text primary key,
  value jsonb not null default '{}'::jsonb,
  is_enabled boolean not null default true,
  updated_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now()
);

alter table public.api_settings enable row level security;

drop policy if exists "api_settings_select_authenticated" on public.api_settings;
create policy "api_settings_select_authenticated"
  on public.api_settings
  for select
  to authenticated
  using (true);

drop policy if exists "api_settings_modify_authenticated" on public.api_settings;
create policy "api_settings_modify_authenticated"
  on public.api_settings
  for all
  to authenticated
  using (true)
  with check (true);

grant select on public.api_settings to anon, authenticated;
grant all on public.api_settings to authenticated;

alter table public.orders
  add column if not exists payment_provider text,
  add column if not exists payment_reference text,
  add column if not exists customer_mobile text,
  add column if not exists phonepe_transaction_id text,
  add column if not exists phonepe_merchant_transaction_id text,
  add column if not exists whatsapp_notified boolean not null default false,
  add column if not exists whatsapp_notified_at timestamptz,
  add column if not exists payment_meta jsonb;

alter table public.orders
  add column if not exists whatsapp_seller_notified boolean not null default false,
  add column if not exists whatsapp_seller_notified_at timestamptz;

alter table if exists public.products
  add column if not exists product_code text;

alter table if exists public.products
  add column if not exists is_draft boolean not null default false;

create unique index if not exists products_product_code_unique
  on public.products (product_code)
  where product_code is not null;

-- Product sale discount: MRP stays in price; discount_percent reduces customer price.
ALTER TABLE products
  ADD COLUMN IF NOT EXISTS discount_enabled boolean NOT NULL DEFAULT false;

ALTER TABLE products
  ADD COLUMN IF NOT EXISTS discount_percent integer;

COMMENT ON COLUMN products.price IS 'List / MRP price in INR';
COMMENT ON COLUMN products.discount_enabled IS 'When true, sale price = price reduced by discount_percent';
COMMENT ON COLUMN products.discount_percent IS 'Integer 1-99; required when discount_enabled is true';

-- Faster admin product list ordering and draft/featured lookups.
create index if not exists products_created_at_desc_idx
  on public.products (created_at desc nulls last);

create index if not exists products_featured_idx
  on public.products (featured)
  where featured = true;

create index if not exists products_is_draft_idx
  on public.products (is_draft)
  where is_draft = true;

-- Optional pack/set label: qty remains packs; pack_size is display-only.
ALTER TABLE products
  ADD COLUMN IF NOT EXISTS sold_as_pack boolean NOT NULL DEFAULT false;

ALTER TABLE products
  ADD COLUMN IF NOT EXISTS pack_size integer;

COMMENT ON COLUMN products.sold_as_pack IS 'When true, show Set of N near price; cart qty = number of packs';
COMMENT ON COLUMN products.pack_size IS 'Pieces per set when sold_as_pack; required integer >= 2 when enabled';

-- Faster admin media gallery ORDER BY created_at DESC, id DESC.
create index if not exists medias_created_at_id_desc_idx
  on public.medias (created_at desc nulls last, id desc);
